import React, { useEffect, useState, useCallback } from 'react';
import { useAuth } from '../context/AuthContext';
import api, { getImageUrl } from '../services/api';
import { motion, AnimatePresence } from 'framer-motion';
import { Link } from 'react-router-dom';
import styles from './UserDashboard.module.css';

const UserDashboard = () => {
  const { user, setUser, notifications, clearNotifications } = useAuth();
  const [activeTab, setActiveTab] = useState('profile');
  const [purchases, setPurchases] = useState([]);
  const [testDrives, setTestDrives] = useState([]);
  const [loans, setLoans] = useState([]);
  const [favorites, setFavorites] = useState([]);
  const [compareIds, setCompareIds] = useState([]); // Храним только ID выбранных для сравнения авто
  const [loading, setLoading] = useState(true);
  
  // Состояния для редактирования профиля
  const [profileForm, setProfileForm] = useState({
    full_name: user?.full_name || '',
    phone: user?.phone || '',
  });
  const [updateStatus, setUpdateStatus] = useState(null);

  // Состояния для отправки отзывов по тест-драйвам
  const [reviewForm, setReviewForm] = useState({
    test_drive_id: null,
    rating: 5,
    comment: ''
  });

  // Состояние ввода пользовательских комментариев для кредитов (по ID кредита)
  const [loanCommentsInput, setLoanCommentsInput] = useState({});

  const tabs = [
    { key: 'profile', label: 'Профиль' },
    { key: 'purchases', label: 'История покупок' },
    { key: 'testdrives', label: 'Тест-драйвы' },
    { key: 'loans', label: 'Кредитные заявки' },
    { key: 'favorites', label: 'Избранное' },
    { key: 'compare', label: 'Сравнение авто' },
    { key: 'notifications', label: 'Уведомления' }
  ];

  // ================= ЗАГРУЗКА ДАННЫХ =================
  const fetchData = useCallback(async () => {
    try {
      setLoading(true);
      const [pRes, tRes, lRes] = await Promise.all([
        api.get('/purchases/my').catch(() => ({ data: [] })),
        api.get('/testdrives/my').catch(() => ({ data: [] })),
        api.get('/loans/my').catch(() => ({ data: [] })),
      ]);
      setPurchases(pRes.data);
      setTestDrives(tRes.data);
      setLoans(lRes.data);

      // Читаем Избранное
      const cachedFavs = JSON.parse(localStorage.getItem('favorites') || '[]');
      setFavorites(cachedFavs);

      // Читаем ID машин для сравнения
      const cachedCompareIds = JSON.parse(localStorage.getItem('compareIds') || '[]');
      setCompareIds(cachedCompareIds);
    } catch (err) {
      console.error('Ошибка при загрузке данных ЛК:', err);
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    fetchData();
  }, [fetchData]);

  // Обновление данных профиля
  const handleProfileSubmit = async (e) => {
    e.preventDefault();
    setUpdateStatus(null);
    try {
      const res = await api.put('/auth/profile', profileForm);
      setUser(res.data);
      setUpdateStatus({ type: 'success', text: 'Профиль успешно обновлен' });
    } catch (err) {
      setUpdateStatus({ type: 'error', text: 'Не удалось обновить профиль. Попробуйте позже.' });
    }
  };

  // Извлечение безопасного ID машины
  const getCarId = (car) => {
    if (!car) return null;
    return car.id || car.car_id || null;
  };

  // Удаление из избранного
  const removeFavorite = (carId) => {
    if (!carId) return;
    const updated = favorites.filter(car => getCarId(car) !== carId);
    setFavorites(updated);
    localStorage.setItem('favorites', JSON.stringify(updated));
    
    const updatedCompare = compareIds.filter(cId => cId !== carId);
    setCompareIds(updatedCompare);
    localStorage.setItem('compareIds', JSON.stringify(updatedCompare));
  };

  // Переключение машины в списке сравнения
  const toggleCompare = (carId) => {
    if (!carId) return;
    let updated;
    if (compareIds.includes(carId)) {
      updated = compareIds.filter(id => id !== carId);
    } else {
      updated = [...compareIds, carId];
    }
    setCompareIds(updated);
    localStorage.setItem('compareIds', JSON.stringify(updated));
  };

  // Отправка отзыва по тест-драйву
  const handleReviewSubmit = async (e) => {
    e.preventDefault();
    if (!reviewForm.test_drive_id) return;
    try {
      await api.post(`/testdrives/${reviewForm.test_drive_id}/review`, {
        rating: reviewForm.rating,
        comment: reviewForm.comment
      });
      alert('Отзыв успешно отправлен!');
      setReviewForm({ test_drive_id: null, rating: 5, comment: '' });
      fetchData();
    } catch (err) {
      console.error('Ошибка отправки отзыва:', err);
      alert('Не удалось отправить отзыв.');
    }
  };

  // Отправка пользовательского комментария к кредиту
  const handleSendLoanComment = async (loanId) => {
    const text = loanCommentsInput[loanId];
    if (text === undefined || text.trim() === '') {
      alert('Пожалуйста, введите текст комментария');
      return;
    }

    try {
      const response = await api.post(`/loans/${loanId}/comment`, {
        user_comment: text
      });
      setLoans(loans.map(loan => loan.id === loanId ? response.data : loan));
      alert('Комментарий успешно сохранен!');
    } catch (error) {
      console.error('Ошибка при сохранении комментария кредита:', error);
      alert('Не удалось сохранить комментарий.');
    }
  };

  const resolveCarImage = (car) => {
    if (car?.image_url) return getImageUrl(car.image_url);
    if (car?.images && car.images.length > 0) return getImageUrl(car.images[0].image_url);
    return '/fallback-car.jpg';
  };

  const isFieldDifferent = (field) => {
    const selectedCars = favorites.filter(car => compareIds.includes(getCarId(car)));
    if (selectedCars.length < 2) return false;
    const firstVal = selectedCars[0]?.[field];
    return selectedCars.some(car => car[field] !== firstVal);
  };

  const renderTabContent = () => {
    switch (activeTab) {
      case 'profile':
        return (
          <div className={styles.profileSection}>
            <h3>Ваши данные</h3>
            <form onSubmit={handleProfileSubmit} className={styles.profileForm}>
              <div className={styles.field}>
                <label>ФИО</label>
                <input
                  type="text"
                  value={profileForm.full_name}
                  onChange={(e) => setProfileForm({ ...profileForm, full_name: e.target.value })}
                  required
                />
              </div>
              <div className={styles.field}>
                <label>Телефон</label>
                <input
                  type="text"
                  value={profileForm.phone}
                  onChange={(e) => setProfileForm({ ...profileForm, phone: e.target.value })}
                />
              </div>
              <button type="submit" className={styles.submitBtn}>Сохранить изменения</button>
              {updateStatus && (
                <p className={updateStatus.type === 'success' ? styles.successText : styles.errorText}>
                  {updateStatus.text}
                </p>
              )}
            </form>
          </div>
        );

      case 'purchases':
        return purchases.length > 0 ? (
          <div className={styles.cardsGrid}>
            {purchases.map((purchase) => (
              <div key={purchase.id} className={`${styles.card} ${styles.receiptCard}`}>
                <div className={styles.receiptHeader}>
                  <h4>ЧЕК ОПЛАТЫ №{purchase.id}</h4>
                  <span>{new Date(purchase.created_at).toLocaleDateString()}</span>
                </div>
                <div className={styles.receiptBody}>
                  <div className={styles.receiptRow}>
                    <span>Автомобиль:</span>
                    <strong>{purchase.car_brand} {purchase.car_model} ({purchase.car_year})</strong>
                  </div>
                  <div className={styles.receiptRow}>
                    <span>Способ оплаты:</span>
                    <strong>{purchase.payment_method === 'credit' ? 'Автокредит' : 'Банковская карта'}</strong>
                  </div>
                  <div className={styles.receiptRow}>
                    <span>Итоговая стоимость:</span>
                    <strong className={styles.price}>{purchase.amount.toLocaleString()} ₽</strong>
                  </div>
                  <div className={styles.receiptRow}>
                    <span>Статус плательщика:</span>
                    <strong>Владелец подтвержден</strong>
                  </div>
                </div>
                <button className={styles.printBtn} onClick={() => window.print()}>
                  Распечатать чек (PDF)
                </button>
              </div>
            ))}
          </div>
        ) : (
          <p className={styles.empty}>У вас пока нет оформленных покупок автомобилей.</p>
        );

      case 'testdrives':
        return testDrives.length > 0 ? (
          <div className={styles.cardsGrid}>
            {testDrives.map((td) => (
              <div key={td.id} className={styles.card}>
                <div className={styles.cardHeader}>Тест-драйв заявка №{td.id}</div>
                <div className={styles.cardBody}>
                  <p><strong>Дата:</strong> {new Date(td.preferred_date).toLocaleDateString()}</p>
                  <p><strong>Статус:</strong> <span className={styles[`status_${td.status}`]}>{td.status}</span></p>
                  {td.message && <p><strong>Ваше сообщение:</strong> {td.message}</p>}
                  {td.admin_comment && <p><strong>Ответ автосалона:</strong> {td.admin_comment}</p>}
                  
                  {td.status === 'completed' && !reviewForm.test_drive_id && (
                    <button className={styles.actionBtn} onClick={() => setReviewForm({ ...reviewForm, test_drive_id: td.id })}>
                      Оставить отзыв
                    </button>
                  )}

                  {reviewForm.test_drive_id === td.id && (
                    <form onSubmit={handleReviewSubmit} className={styles.profileForm} style={{ marginTop: '1rem' }}>
                      <div className={styles.field}>
                        <label>Оценка (1-5):</label>
                        <input 
                          type="number" min="1" max="5" 
                          value={reviewForm.rating} 
                          onChange={(e) => setReviewForm({ ...reviewForm, rating: parseInt(e.target.value) })}
                          required
                        />
                      </div>
                      <div className={styles.field}>
                        <label>Комментарий:</label>
                        <textarea 
                          value={reviewForm.comment} 
                          onChange={(e) => setReviewForm({ ...reviewForm, comment: e.target.value })}
                          rows="3"
                          style={{ padding: '0.5rem', borderRadius: '8px', border: '1px solid rgba(128,128,128,0.3)', background: 'transparent', color: 'var(--text)' }}
                          required
                        />
                      </div>
                      <div style={{ display: 'flex', gap: '0.5rem' }}>
                        <button type="submit" className={styles.submitBtn}>Отправить</button>
                        <button type="button" className={styles.cancelBtn} onClick={() => setReviewForm({ ...reviewForm, test_drive_id: null })}>Отмена</button>
                      </div>
                    </form>
                  )}
                </div>
              </div>
            ))}
          </div>
        ) : (
          <p className={styles.empty}>У вас пока нет заявок на тест-драйв.</p>
        );

      case 'loans':
        return loans.length > 0 ? (
          <div className={styles.cardsGrid}>
            {loans.map((loan) => (
              <div key={loan.id} className={styles.card}>
                <div className={styles.cardHeader}>Кредитная заявка №{loan.id}</div>
                <div className={styles.cardBody}>
                  <p><strong>Сумма кредита:</strong> {loan.amount.toLocaleString()} ₽</p>
                  <p><strong>Срок:</strong> {loan.term_months} мес.</p>
                  <p><strong>Ежемесячный платёж:</strong> {loan.monthly_payment.toLocaleString()} ₽</p>
                  <p><strong>Переплата:</strong> {loan.overpayment.toLocaleString()} ₽</p>
                  <p><strong>Статус:</strong> <span className={styles[`status_${loan.status}`]}>{loan.status}</span></p>

                  {loan.admin_comment && (
                    <div className={styles.adminCommentBox}>
                      <h5>Решение автосалона:</h5>
                      <p>{loan.admin_comment}</p>
                    </div>
                  )}

                  {loan.user_comment && (
                    <div className={styles.userCommentBox}>
                      <h5>Ваше примечание/комментарий:</h5>
                      <p>{loan.user_comment}</p>
                    </div>
                  )}

                  <div className={styles.commentForm}>
                    <textarea
                      placeholder="Добавить комментарий или заметку к заявке..."
                      rows="2"
                      value={loanCommentsInput[loan.id] !== undefined ? loanCommentsInput[loan.id] : (loan.user_comment || '')}
                      onChange={(e) => setLoanCommentsInput({
                        ...loanCommentsInput,
                        [loan.id]: e.target.value
                      })}
                    />
                    <button 
                      className={styles.commentSubmitBtn}
                      onClick={() => handleSendLoanComment(loan.id)}
                    >
                      {loan.user_comment ? 'Обновить комментарий' : 'Оставить комментарий'}
                    </button>
                  </div>
                </div>
              </div>
            ))}
          </div>
        ) : (
          <p className={styles.empty}>У вас пока нет оформленных кредитных заявок.</p>
        );

      case 'favorites':
        return favorites.length > 0 ? (
          <div className={styles.favoritesGrid}>
            {favorites.map((car, idx) => {
              const carId = getCarId(car);
              const brand = car.brand || car.car_brand || 'Premium';
              const model = car.model || car.car_model || 'Car';
              const imgPath = resolveCarImage(car);
              const fallbackKey = carId ? `fav-${carId}` : `fav-idx-${idx}`;

              return (
                <div key={fallbackKey} className={styles.favCard}>
                  <img src={imgPath} alt={`${brand} ${model}`} className={styles.favImage} />
                  <div className={styles.favInfo}>
                    <h4>{brand} {model}</h4>
                    <p className={styles.price}>{car.price?.toLocaleString()} ₽</p>
                    <div className={styles.favActions}>
                      <Link to={`/catalog/${carId}`} className={styles.detailsLink}>Подробнее</Link>
                      <button className={styles.removeBtn} onClick={() => removeFavorite(carId)}>Удалить</button>
                      <button 
                        className={`${styles.compareBtn} ${compareIds.includes(carId) ? styles.activeCompare : ''}`} 
                        onClick={() => toggleCompare(carId)}
                      >
                        {compareIds.includes(carId) ? 'В сравнении' : 'Сравнить'}
                      </button>
                    </div>
                  </div>
                </div>
              );
            })}
          </div>
        ) : (
          <p className={styles.empty}>Список избранного пуст.</p>
        );

      case 'compare':
        const selectedCars = favorites.filter(car => compareIds.includes(getCarId(car)));
        return selectedCars.length > 0 ? (
          <div className={styles.compareContainer}>
            <div className={styles.compareTable}>
              <div className={styles.compareRow}>
                <div className={styles.compareLabel}>Модель</div>
                {selectedCars.map(car => (
                  <div key={`name-${getCarId(car)}`} className={styles.compareValue}>
                    <strong>{car.brand} {car.model}</strong>
                  </div>
                ))}
              </div>
              <div className={styles.compareRow}>
                <div className={styles.compareLabel}>Цена</div>
                {selectedCars.map(car => (
                  <div key={`price-${getCarId(car)}`} className={styles.compareValue}>
                    {car.price?.toLocaleString()} ₽
                  </div>
                ))}
              </div>
              <div className={styles.compareRow}>
                <div className={styles.compareLabel}>Год выпуска</div>
                {selectedCars.map(car => (
                  <div key={`year-${getCarId(car)}`} className={styles.compareValue}>{car.year}</div>
                ))}
              </div>
              <div className={styles.compareRow}>
                <div className={styles.compareLabel}>Привод</div>
                {selectedCars.map(car => (
                  <div key={`drive-${getCarId(car)}`} className={`${styles.compareValue} ${isFieldDifferent('drive_type') ? styles.diffField : ''}`}>
                    {car.drive_type || '—'}
                  </div>
                ))}
              </div>
              <div className={styles.compareRow}>
                <div className={styles.compareLabel}>Коробка передач</div>
                {selectedCars.map(car => (
                  <div key={`trans-${getCarId(car)}`} className={`${styles.compareValue} ${isFieldDifferent('transmission') ? styles.diffField : ''}`}>
                    {car.transmission || '—'}
                  </div>
                ))}
              </div>
            </div>
          </div>
        ) : (
          <p className={styles.empty}>Добавьте автомобили из избранного для сравнения характеристик.</p>
        );

      case 'notifications':
        return notifications && notifications.length > 0 ? (
          <div className={styles.notificationsList}>
            {notifications.map((msgText, idx) => (
              <div key={`notification-${idx}`} className={`${styles.card} ${styles.notificationCard}`}>
                <div className={styles.cardBody}>{msgText}</div>
              </div>
            ))}
            <button className={styles.clearBtn} onClick={clearNotifications}>
              Очистить логи уведомлений
            </button>
          </div>
        ) : (
          <p className={styles.empty}>Новых уведомлений нет.</p>
        );

      default:
        return null;
    }
  };

  if (loading) return <div className={styles.loading}>Синхронизация данных профиля...</div>;

  return (
    <motion.div className={styles.container} initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ duration: 0.5 }}>
      <h2 className={styles.title}>Личный кабинет – {user?.full_name || 'Клиент'}</h2>
      
      <div className={styles.tabs}>
        {tabs.map(tab => (
          <button
            key={`tab-btn-${tab.key}`}
            className={`${styles.tab} ${activeTab === tab.key ? styles.active : ''}`}
            onClick={() => setActiveTab(tab.key)}
          >
            {tab.label} {tab.key === 'compare' && compareIds.length > 0 && `(${compareIds.length})`}
          </button>
        ))}
      </div>

      <div className={styles.tabContentWindow}>
        <AnimatePresence mode="wait">
          <motion.div
            key={activeTab}
            initial={{ opacity: 0, y: 10 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: -10 }}
            transition={{ duration: 0.2 }}
          >
            {renderTabContent()}
          </motion.div>
        </AnimatePresence>
      </div>
    </motion.div>
  );
};

export default UserDashboard;
